import React from 'react';

// value.svg is generated by this app's own DrawingFieldInput (react-sketch-canvas's
// exportSvg()), not user-pasted markup, so rendering it directly is the same trust
// level as any other app-authored content.
export default function DrawingFieldRenderer({ value }) {
  if (!value?.svg) return null;
  return (
    <div
      className="max-w-full w-fit overflow-auto rounded-md border border-stone-200 dark:border-stone-700 bg-white p-2"
      dangerouslySetInnerHTML={{ __html: value.svg }}
    />
  );
}
